// Every video in src/assets ships as <name>.webm (VP9) plus, when generated by
// scripts/encode-videos.sh, <name>.mp4 (H.264, or HEVC with alpha for
// transparent clips) and <name>.poster.webp. Components keep importing the
// .webm; this module finds its siblings so call sites stay unchanged.

// (Vite only reads glob options written inline, so they're repeated here.)
const webms = import.meta.glob<string>('../assets/**/*.webm', { eager: true, query: '?url', import: 'default' });
const mp4s = import.meta.glob<string>('../assets/**/*.mp4', { eager: true, query: '?url', import: 'default' });
const posters = import.meta.glob<string>('../assets/**/*.poster.webp', { eager: true, query: '?url', import: 'default' });

export interface VideoSource {
  src: string;
  type: string;
}

interface VideoEntry {
  webm: string;
  mp4?: string;
  poster?: string;
}

const normalize = (url: string) => {
  const path = url.split('?')[0];
  try {
    return decodeURI(path);
  } catch {
    return path;
  }
};

const byUrl = new Map<string, VideoEntry>();
for (const [path, webm] of Object.entries(webms)) {
  const stem = path.slice(0, -'.webm'.length);
  byUrl.set(normalize(webm), {
    webm,
    mp4: mp4s[`${stem}.mp4`],
    poster: posters[`${stem}.poster.webp`],
  });
}

// Safari and every iOS browser (all WebKit) get the MP4 first: it is hardware
// decoded there, and WebKit cannot draw VP9 transparency.
const preferMp4 =
  typeof navigator !== 'undefined' &&
  /AppleWebKit/.test(navigator.userAgent) &&
  !/Chrome|Chromium|Android/.test(navigator.userAgent);

/** Sources (best first) and poster for a video imported as its .webm URL. */
export function videoSources(webmUrl: string): { sources: VideoSource[]; poster?: string } {
  const entry = byUrl.get(normalize(webmUrl));
  const webm: VideoSource = { src: entry?.webm ?? webmUrl, type: 'video/webm' };
  if (!entry?.mp4) return { sources: [webm], poster: entry?.poster };
  const mp4: VideoSource = { src: entry.mp4, type: 'video/mp4' };
  return { sources: preferMp4 ? [mp4, webm] : [webm, mp4], poster: entry.poster };
}
